mapper.select:
SELECT EXISTS(SELECT 1 FROM pf.knowledge_index_chunk WHERE space_id=#{command.spaceId}
  AND document_id=#{command.documentId} AND index_version=#{command.indexVersion} AND ordinal=#{chunk.ordinal}
  AND chunk_sha256=#{chunk.sha256} AND body=#{chunk.body})

SELECT EXISTS(SELECT 1 FROM pf.knowledge_index_build b JOIN pf.knowledge_document d ON d.id=b.document_id AND d.space_id=b.space_id
  WHERE b.id=#{command.buildId} AND b.state='RUNNING' AND b.owner_id=#{command.ownerId} AND b.generation=#{command.generation} AND b.fence=#{command.fence}
   AND b.lease_until>clock_timestamp() AND d.status<>'DELETED' AND d.extraction_id=#{command.extractionId}
   AND pf.authorize_workspace_actor(d.owner_user_id,d.space_id) AND d.owner_user_id=#{command.actorId})
